                    .uri("/verify/email?email={email}", email)
                    .retrieve()
                    .body(new ParameterizedTypeReference<>() {
                    });

            if (body == null) {
                return false;
            }

            return Boolean.TRUE.equals(body.get("valid"));
        } catch (Exception e) {
            return false;
        }
    }

    /**
